from lib import *
S = SS('n45')
steps = [
    step("BasicAuth 在注册时把每个账号预先算成完整的头值 \"Basic \" + base64(user:password)(processAccounts,账号为空或用户名为空会 panic),请求时 searchCredential 拿 Authorization 头去和每个账号的预算值逐个做 subtle.ConstantTimeCompare;命中就 c.Set(AuthUserKey, user) 放行,否则设 WWW-Authenticate 并 AbortWithStatus(401)。", t=tl(S(1)), mark=lidx(S(1), 'subtle.ConstantTimeCompare', 'c.Header("WWW-Authenticate", realm)', 'c.AbortWithStatus(http.StatusUnauthorized)'), done=lidx(S(1), 'assert1(user != "", "User can not be empty")', 'value := authorizationHeader(user, password)', 'c.Set(AuthUserKey, user)'), kv=KV([['预计算', '"Basic " + base64(user:pass)'], ['比较', '整个头值,逐个账号 ConstantTimeCompare'], ['成功', 'c.Set(AuthUserKey, user)']], ['预计算'])),
    step("行为:正确的 alice、密码里有冒号的 bob、中文账号 → 200,c.MustGet(gin.AuthUserKey) 取到用户名;密码错、用户不存在、没有 Authorization 头 → 401、空正文、WWW-Authenticate: Basic realm=\"Authorization Required\";因为是整串比较,小写的 scheme basic …、scheme 后多一个空格、去掉了 = 填充的 base64(al:pw)都是 401(RFC 允许 scheme 不区分大小写,Gin 不允许);Bearer 令牌、空用户名也是 401。组里不存在的路径 /admin/nothing 不带凭据直接 404,不会要求认证。", t=tl(S(2)), mark=lidx(S(2), '小写 scheme', 'scheme 后多一个空格', '去掉 = 填充', '/admin/nothing'), done=lidx(S(2), '正确的 alice', '正确的 bob', '正确的 中文', 'al:pw 的 base64 带 = 填充'), kv=KV([['整串比较', '大小写、空格、填充都必须一致'], ['失败', '401 + WWW-Authenticate,空正文'], ['组里的 404', '不经过认证,不会 401']], ['整串比较'])),
    step("realm 与代理认证:默认 realm 是 Authorization Required,BasicAuthForRealm 的自定义 realm 用 strconv.Quote 转义(我的 \\\"后台\\\");BasicAuthForProxy 看的是 Proxy-Authorization,失败返回 407 与 Proxy-Authenticate(realm 默认 Proxy Authorization Required),成功时用户名放在 AuthProxyUserKey(\"proxy_user\")里,带的是 Authorization 头则仍是 407;账号用户名为空 → panic: User can not be empty;空 Accounts → panic: Empty list of authorized credentials。", t=tl(S(3)), mark=lidx(S(3), 'BasicAuthForProxy 没有凭据', '带的是 Authorization', 'panic: User can not be empty', '空 Accounts'), done=lidx(S(3), '自定义 realm', '默认 realm', 'BasicAuthForProxy 带 Proxy-Authorization'), kv=KV([['realm', '默认 "Authorization Required",可自定义'], ['代理认证', 'Proxy-Authorization → 407'], ['空账号', '注册时 panic']], ['代理认证'])),
    step("账号数量与耗时(5 轮中位数,两轮一致):错误凭据的长度与所有账号的头值都不同时,ConstantTimeCompare 一看长度不同就返回,1000 个账号也只要 1.56 µs;凭据长度恰好和账号头值相同(userXXXX:password-0000)就要逐字节比较:1 个账号 510 ns,10 个 658 ns,100 个 2016 ns,1000 个账号 14465 ns。每个请求要遍历所有账号,账号多时认证成了主要开销;而且耗时会泄漏“长度是否匹配”。", t=tl(S(4)), mark=lidx(S(4), '1000 个账号', '100 个账号'), done=lidx(S(4), '1 个账号', '10 个账号'), b=bars([['1000 个账号:长度不同', 1562, '1.56 µs'], ['1000 个账号:长度相同', 14465, '14.5 µs'], ['100 个账号:长度相同', 2016, '2.0 µs'], ['10 个账号:长度相同', 658, '0.66 µs']], 14465, mark=[1], done=[0, 2, 3]), kv=KV([['每请求遍历所有账号', '账号多时线性增长'], ['长度不同', '立刻返回,便宜'], ['长度相同', '逐字节比较,贵 9 倍(1000 账号)']], ['每请求遍历所有账号'])),
]
A = mkartn('n45', 45, 'Gin,BasicAuth,HTTP认证,401,常量时间比较,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 BasicAuth:账号预先算成 "Basic base64" 头值,整串做常量时间比较,所以小写 scheme、多余空格、去掉 = 填充都是 401;失败返回 401 与 WWW-Authenticate,BasicAuthForProxy 返回 407;组里的 404 不要求认证;每个请求遍历全部账号,1000 个账号时长度相同的错误凭据 14.4 µs、长度不同只要 1.56 µs。',
    '用 gin.BasicAuth 加一道简单认证只要一行,但它怎么比较、哪些写法会被拒、组里的 404 要不要认证、账号多了会慢多少?这篇从源码到各种凭据写法,再到账号数量与耗时,把 BasicAuth 的行为核对一遍。',
    [('401', '密码错、用户不存在、没有头、小写 basic、Bearer 令牌都是 401 加 WWW-Authenticate'), ('1.56 vs 14.5 µs', '1000 个账号时,长度不同与长度相同的错误凭据的耗时'), ('404 不认证', '/admin/nothing(组内不存在的路径)不带凭据也是 404,不会返回 401')],
    [('实现', '<p>BasicAuth 的实现只有几十行:账号在启动时预先算成完整的头值,请求时拿 <code>Authorization</code> 头去比对。比较用的是 <code>subtle.ConstantTimeCompare</code>,所以逐字节的比较时间不依赖内容。认证成功后用户名放在 <code>c.Keys["user"]</code>(<code>gin.AuthUserKey</code>)里。</p>'),
     ('什么写法会被拒', '<p>因为是整串比较,<code>Authorization</code> 头必须与 <code>Basic </code> + 标准 base64(带 = 填充)完全一致:小写的 scheme、多余空格、去掉填充的 base64 都会 401,即使 RFC 允许 scheme 不区分大小写。绝大多数客户端(浏览器、curl、各语言的 HTTP 库)发出的格式是对的,但自己拼头的脚本要小心。失败总是 401 加 <code>WWW-Authenticate</code>、空正文。</p>'),
     ('realm 与代理', '<p>realm 默认是 <code>Authorization Required</code>,可以用 <code>BasicAuthForRealm</code> 自定义;<code>BasicAuthForProxy</code> 对应代理认证,读 <code>Proxy-Authorization</code>、返回 407。账号表为空、用户名为空会在注册时 panic。注意组里的 404(路径不存在)不经过组的中间件,所以不会要求认证——这不是漏洞,但会让探测者能区分“存在的受保护路径”与“不存在的路径”。</p>'),
     ('性能与计时', '<p>每个请求都要把头与<b>所有</b>账号比较,账号数线性增长:1000 个账号、长度恰好匹配时一次比较要 14 µs。<code>ConstantTimeCompare</code> 在两个值长度不同时立刻返回,所以整体耗时会泄漏“长度是否匹配”(几十纳秒到微秒级的差别,通过网络很难利用,但它不是严格的常量时间)。需要几百个以上的账号时应该换成按用户名查表再比较密码哈希的实现。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 直接调用 ServeHTTP;耗时是 testing.Benchmark 的 5 轮中位数(每次迭代包含新建 httptest.NewRecorder,所以有约 500 ns 的底噪),整个实验跑了两轮;账号是 user0000…user0999 对应 password-0000…',
     '没有验证:网络上能否实际测出长度泄漏(只在进程内测了耗时);密码哈希(bcrypt)的替代实现;HTTPS 之外的明文风险(BasicAuth 只是 base64,必须配合 TLS,这是常识,没有实验);暴力破解的限流;并发下遍历账号的开销'],
    'BasicAuth')
